14	class SessionVerificationScreenViewModel: SessionVerificationViewModelType, SessionVerificationScreenViewModelProtocol {
15	    private let sessionVerificationControllerProxy: SessionVerificationControllerProxyProtocol
16	    private let flow: SessionVerificationScreenFlow
17	    
18	    private var stateMachine: SessionVerificationScreenStateMachine
19	
20	    private var actionsSubject: PassthroughSubject<SessionVerificationScreenViewModelAction, Never> = .init()
21	    
22	    var actions: AnyPublisher<SessionVerificationScreenViewModelAction, Never> {
23	        actionsSubject.eraseToAnyPublisher()
24	    }
25	
26	    init(sessionVerificationControllerProxy: SessionVerificationControllerProxyProtocol,
27	         flow: SessionVerificationScreenFlow,
28	         appSettings: AppSettings,
29	         mediaProvider: MediaProviderProtocol,
30	         verificationState: SessionVerificationScreenStateMachine.State = .initial) {
31	        self.sessionVerificationControllerProxy = sessionVerificationControllerProxy
32	        self.flow = flow
33	        
34	        stateMachine = SessionVerificationScreenStateMachine(state: verificationState)
35	        
36	        super.init(initialViewState: .init(flow: flow,
37	                                           learnMoreURL: appSettings.encryptionURL,
38	                                           verificationState: verificationState),
39	                   mediaProvider: mediaProvider)
40	        
41	        setupStateMachine()
42	        
43	        sessionVerificationControllerProxy.actions
44	            .receive(on: DispatchQueue.main)
45	            .sink { [weak self] callback in
46	                guard let self else { return }
47	                
48	                switch callback {
49	                case .receivedVerificationRequest:
50	                    break // Incoming verification requests are handled on the higher levels
51	                case .acceptedVerificationRequest:
52	                    self.stateMachine.processEvent(.didAcceptVerificationRequest)
53	                case .startedSasVerification:
54	                    self.stateMachine.processEvent(.didStartSasVerification)
55	                case .receivedVerificationData(let emojis):
56	                    guard self.stateMachine.state == .sasVerificationStarted else {
57	                        MXLog.warning("Callbacks: Ignoring receivedVerificationData due to invalid state.")
58	                        return
59	                    }
60	                    
61	                    self.stateMachine.processEvent(.didReceiveChallenge(emojis: emojis))
62	                case .finished:
63	                    self.stateMachine.processEvent(.didAcceptChallenge)
64	                case .cancelled:
65	                    self.stateMachine.processEvent(.didCancel)
66	                case .failed:
67	                    self.stateMachine.processEvent(.didFail)
68	                }
69	            }
70	            .store(in: &cancellables)
71	        
72	        switch flow {
73	        case .deviceResponder(let details), .userResponder(let details):
74	            Task {
75	                await self.sessionVerificationControllerProxy.acknowledgeVerificationRequest(details: details)
76	            }
77	        default:
78	            break
79	        }
80	    }
81	    
82	    override func process(viewAction: SessionVerificationScreenViewAction) {
83	        switch viewAction {
84	        case .acceptVerificationRequest:
85	            stateMachine.processEvent(.acceptVerificationRequest)
86	        case .ignoreVerificationRequest:
87	            actionsSubject.send(.finished)
88	        case .requestVerification:
89	            stateMachine.processEvent(.requestVerification)
90	        case .restart:
91	            stateMachine.processEvent(.restart)
92	        case .accept:
93	            stateMachine.processEvent(.acceptChallenge)
94	        case .decline:
95	            stateMachine.processEvent(.declineChallenge)
96	        case .cancel:
97	            stateMachine.processEvent(.cancel)
98	            actionsSubject.send(.finished)
99	        case .done:
100	            actionsSubject.send(.finished)
101	        }
102	    }
103	    
104	    func stop() {
105	        switch stateMachine.state {
106	        case .initial, .verified, .cancelled: // non-cancellable states
107	            return
108	        default:
109	            stateMachine.processEvent(.cancel)
110	        }
111	    }
112	    
113	    // MARK: - Private
114	    
115	    private func setupStateMachine() {
116	        stateMachine.addTransitionHandler { [weak self] context in
117	            guard let self else { return }
118	                
119	            state.verificationState = context.toState
120	            
121	            switch (context.fromState, context.event, context.toState) {
122	            case (.initial, .acceptVerificationRequest, .acceptingVerificationRequest):
123	                acceptVerificationRequest()
124	            case (.initial, .requestVerification, .requestingVerification):
125	                Task {
126	                    switch await self.requestVerification() {
127	                    case .success:
128	                        // Need to wait for the callback from the remote
129	                        break
130	                    case .failure:
131	                        self.stateMachine.processEvent(.didFail)
132	                    }
133	                }
134	            case (.acceptingVerificationRequest, .didAcceptVerificationRequest, .verificationRequestAccepted):
135	                startSasVerification()
136	            case (.showingChallenge, .acceptChallenge, .acceptingChallenge):
137	                acceptChallenge()
138	            case (.showingChallenge, .declineChallenge, .decliningChallenge):
139	                declineChallenge()
140	            case (_, .cancel, .cancelling):
141	                cancelVerification()
142	            case (_, _, .verified):
143	                actionsSubject.send(.finished)
144	            case (.initial, _, .cancelled):
145	                switch flow {
146	                case .deviceResponder, .userResponder:
147	                    actionsSubject.send(.finished)
148	                default:
149	                    break
150	                }
151	            default:
152	                break
153	            }
154	        }
155	        
156	        stateMachine.addErrorHandler { context in
157	            MXLog.error("Failed transition with context: \(context)")
158	        }
159	    }
160	    
161	    private func acceptVerificationRequest() {
162	        Task {
163	            guard flow.isResponder else {
164	                fatalError("Incorrect API usage.")
165	            }
166	            
167	            switch await sessionVerificationControllerProxy.acceptVerificationRequest() {
168	            case .success:
169	                stateMachine.processEvent(.didAcceptVerificationRequest)
170	            case .failure:
171	                stateMachine.processEvent(.didFail)
172	            }
173	        }
174	    }
175	    
176	    private func requestVerification() async -> Result<Void, SessionVerificationControllerProxyError> {
177	        switch flow {
178	        case .deviceInitiator:
179	            return await sessionVerificationControllerProxy.requestDeviceVerification()
180	        case .userInitiator(let userID):
181	            return await sessionVerificationControllerProxy.requestUserVerification(userID)
182	        default:
183	            fatalError("Incorrect API usage.")
184	        }
185	    }
186	    
187	    private func cancelVerification() {
188	        Task {
189	            switch await sessionVerificationControllerProxy.cancelVerification() {
190	            case .success:
191	                stateMachine.processEvent(.didCancel)
192	            case .failure:
193	                stateMachine.processEvent(.didFail)
194	            }
195	        }
196	    }
197	    
198	    private func startSasVerification() {
199	        Task {
200	            switch await sessionVerificationControllerProxy.startSasVerification() {
201	            case .success:
202	                // Need to wait for the callback from the remote
203	                break
204	            case .failure:
205	                stateMachine.processEvent(.didFail)
206	            }
207	        }
208	    }
209	    
210	    private func acceptChallenge() {
211	        Task {
212	            switch await sessionVerificationControllerProxy.approveVerification() {
213	            case .success:
214	                // Need to wait for the callback from the remote
215	                break
216	            case .failure:
217	                stateMachine.processEvent(.didFail)
218	            }
219	        }
220	    }
221	    
222	    private func declineChallenge() {
223	        Task {
224	            switch await sessionVerificationControllerProxy.declineVerification() {
225	            case .success:
226	                stateMachine.processEvent(.didCancel)
227	            case .failure:
228	                stateMachine.processEvent(.didFail)
229	            }
230	        }
231	    }
232	}
