355	    private func setupSessionVerificationRequestsObserver() {
356	        userSession.clientProxy.sessionVerificationController?.actions
357	            .receive(on: DispatchQueue.main)
358	            .sink { [weak self] action in
359	                guard let self, case .receivedVerificationRequest(let details) = action else {
360	                    return
361	                }
362	                
363	                MXLog.info("Received session verification request")
364	                
365	                if details.senderProfile.userID == userSession.clientProxy.userID {
366	                    presentSessionVerificationScreen(flow: .deviceResponder(requestDetails: details))
367	                } else {
368	                    presentSessionVerificationScreen(flow: .userResponder(requestDetails: details))
369	                }
370	            }
371	            .store(in: &cancellables)
372	    }
