374	    private func presentSessionVerificationScreen(flow: SessionVerificationScreenFlow) {
375	        guard let sessionVerificationController = userSession.clientProxy.sessionVerificationController else {
376	            fatalError("The sessionVerificationController should aways be valid at this point")
377	        }
378	        
379	        let navigationStackCoordinator = NavigationStackCoordinator()
380	        
381	        let parameters = SessionVerificationScreenCoordinatorParameters(sessionVerificationControllerProxy: sessionVerificationController,
382	                                                                        flow: flow,
383	                                                                        appSettings: flowParameters.appSettings,
384	                                                                        mediaProvider: userSession.mediaProvider)
385	        
386	        let coordinator = SessionVerificationScreenCoordinator(parameters: parameters)
387	        
388	        coordinator.actions
389	            .sink { [weak self] action in
390	                switch action {
391	                case .done:
392	                    self?.navigationTabCoordinator.setSheetCoordinator(nil)
393	                }
394	            }
395	            .store(in: &cancellables)
396	        
397	        navigationStackCoordinator.setRootCoordinator(coordinator)
398	        
399	        navigationTabCoordinator.setSheetCoordinator(navigationStackCoordinator)
400	    }
